void status_req_err_add (Status_Req_Err_Code code)
{  
  UInt8 ptr = status_req_err.count % STATUS_REQ_ERR_BUFF_SIZE ;
 
  status_req_err.code [ptr] = code ;

  status_req_err.count++ ;

  nvfs_wr(nvfs_status_req_err , &status_req_err) ;
}

